<?php
require __DIR__.'/../vendor/autoload.php';$app=require __DIR__.'/../bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use App\Models\{DiscountCode,Product,Order};use Illuminate\Support\Facades\DB;use Illuminate\Http\Request;
function check($ok,$m){if(!$ok)throw new RuntimeException($m);echo "PASS: $m\n";}
DB::beginTransaction();try{
$tag='DISC'.strtoupper(bin2hex(random_bytes(4)));$coupon=DiscountCode::create(['type'=>'coupon','name'=>'Test coupon','code'=>$tag,'amount'=>30,'status'=>true]);$gift=DiscountCode::create(['type'=>'gift_card','name'=>'Test gift','code'=>$tag.'G','amount'=>20,'status'=>true]);$service=new App\Services\CheckoutDiscounts;
$d=$service->calculate(100,strtolower($tag),$tag.'G');check($d['discount_amount']===50 && $d['coupon_code']===$tag,'Codes combine and normalize case');check($service->calculate(40,$tag,$tag.'G')['discount_amount']===40,'Discount cannot exceed product subtotal');
$gift->update(['status'=>false]);try{$service->calculate(100,null,$tag.'G');throw new RuntimeException('Inactive accepted');}catch(Illuminate\Validation\ValidationException $e){check(true,'Inactive gift rejected');}$gift->update(['status'=>true]);try{$service->calculate(100,'MISSING',null);throw new RuntimeException('Missing accepted');}catch(Illuminate\Validation\ValidationException $e){check(true,'Unknown coupon rejected');}
$product=Product::create(['name'=>'Discount fixture','category_id'=>App\Models\Category::firstOrFail()->id,'regular_price'=>100,'stock'=>5,'status'=>true]);
function req($data){global $app;$r=Request::create('/checkout','POST',$data);$app->instance('request',$r);$r->setLaravelSession($app->make('session.store'));return $r;}
$items=[['product_id'=>$product->id,'quantity'=>1]];$preview=(new App\Http\Controllers\DiscountCodeController)->preview(req(['items'=>$items,'coupon_code'=>$tag,'gift_card_code'=>$tag.'G','subtotal'=>999]),$service)->getData(true);check($preview['discount_amount']===50,'Preview uses actual catalog price');
$data=['customer_name'=>'Discount fixture','phone'=>'01700000000','address'=>'Fixture address','area'=>'inside_dhaka','payment_method'=>'cash_on_delivery','policy_accepted'=>true,'items'=>$items,'coupon_code'=>$tag,'gift_card_code'=>$tag.'G','total'=>1];(new App\Http\Controllers\CheckoutController)->store(req($data));$order=Order::latest('id')->firstOrFail();check((float)$order->discount_amount===50.0 && (float)$order->total===50+(float)$order->delivery_fee,'Checkout stores server-validated discount and total');check($order->coupon_code===$tag && $order->gift_card_code===$tag.'G','Receipt keeps code snapshots');
$before=Order::count();$stock=$product->fresh()->stock;$coupon->update(['status'=>false]);try{(new App\Http\Controllers\CheckoutController)->store(req($data));throw new RuntimeException('Disabled checkout accepted');}catch(Illuminate\Validation\ValidationException $e){check(Order::count()===$before && $product->fresh()->stock===$stock,'Code disabled after preview rejects checkout without stock changes');}
$admin=App\Models\User::forceCreate(['name'=>'Discount admin','email'=>$tag.'@example.test','password'=>bin2hex(random_bytes(8)),'is_admin'=>true,'is_super_admin'=>true]);Illuminate\Support\Facades\Auth::login($admin);
$kernel=$app->make(Illuminate\Contracts\Http\Kernel::class);foreach(['/admin/coupons','/admin/gift-cards','/admin/coupons/create','/admin/gift-cards/create','/admin/coupons/'.$coupon->id.'/edit','/admin/gift-cards/'.$gift->id.'/edit'] as $path){$r=Request::create($path,'GET');$r->headers->set('X-Inertia','true');$r->headers->set('X-Inertia-Version',app(App\Http\Middleware\HandleInertiaRequests::class)->version($r));$response=$kernel->handle($r);check($response->getStatusCode()===200,'Admin management route '.$path);}
$controller=new App\Http\Controllers\DiscountCodeController;foreach(['coupon'=>'/admin/coupons','gift_card'=>'/admin/gift-cards'] as $type=>$path){$code=$tag.($type==='coupon'?'C':'GC');$r=req(['name'=>'CRUD fixture','code'=>$code,'amount'=>45,'status'=>true]);$r->setUserResolver(fn()=>$admin);$response=$controller->save($r,null,$type);$record=DiscountCode::where('type',$type)->where('code',$code)->first();check($record && str_ends_with($response->getTargetUrl(),$path),'Create saves and redirects to '.$type.' list');$r=req(['name'=>'Edited fixture','code'=>$code,'amount'=>60,'status'=>false]);$r->setUserResolver(fn()=>$admin);$controller->save($r,$record,$type);check($record->fresh()->name==='Edited fixture' && (float)$record->fresh()->amount===60.0 && !$record->fresh()->status,'Edit updates '.$type);$controller->destroy($r,$record,$type);check(!DiscountCode::find($record->id),'Delete removes '.$type);}
check(str_starts_with((new App\Http\Controllers\CheckoutController)->invoice($order)->getContent(),'%PDF'),'Discounted invoice renders valid PDF');
}finally{DB::rollBack();}

